import json
import sys

def main():
    input_file = 'input/data.csv'
    output_data = []

    try:
        with open(input_file, mode='r', encoding='utf-8') as csvfile:
            reader = csv.DictReader(csvfile)
            for row in reader:
                try:
                    # Create the object with specific type casting
                    obj = {
                        "Name": str(row["Name"]),
                        "Age": int(row["Age"]),
                        "Email": str(row["Email"]),
                        "Score": float(row["Score"])
                    }
                    output_data.append(obj)
                except (ValueError, KeyError) as e:
                    # Skip rows with malformed data or missing columns
                    continue

        # Output the JSON array to stdout
        json.dump(output_data, sys.stdout)

    except FileNotFoundError:
        # If file doesn't exist, output an empty array to maintain valid JSON output requirement
        sys.stdout.write("[]")
    except Exception:
        # In case of any other error, output an empty array
        sys.stdout.write("[]")

if __name__ == "__main__":
    main()

import sys

def print_primes_up_to(n):
    """
    Uses the Sieve of Eratosthenes to find and print all 
    prime numbers up to and including n.
    """
    if n < 2:
        return

    # Create a boolean array "is_prime[0..n]" and initialize
    # all entries it as true. A value in is_prime[i] will
    # finally be false if i is Not a prime, else true.
    is_prime = [True] * (n + 1)
    is_prime[0] = is_prime[1] = False

    p = 2
    while (p * p <= n):
        # If is_prime[p] is not changed, then it is a prime
        if is_prime[p]:
            # Update all multiples of p starting from p*p
            for i in range(p * p, n + 1, p):
                is_prime[i] = False
        p += 1

    # Print all prime numbers
    for p in range(2, n + 1):
        if is_prime[p]:
            print(p)

def main():
    # Check if an argument was provided via command line
    if len(sys.argv) != 2:
        # If usage is incorrect, you might want to print a usage message.
        # However, based on the prompt, we just exit.
        return

    try:
        # Convert the command line argument to an integer
        n = int(sys.argv[1])
        print_primes_up_to(n)
    except ValueError:
        # If the argument is not an integer, exit silently or handle error
        pass

if __name__ == "__main__":
    main()

