	if n < 2 {
		return
	}

	// Generate primes using the Sieve of Eratosthenes algorithm
	primesMask := sieveOfEratosthenes(n)

	// Iterate through the mask and print indices that are true
	for i := 2; i <= n; i++ {
		if primesMask[i] {
