	description string
	price       float64
	quantity    int
	expected    float64
}

func main() {
	// Define test cases covering boundary conditions
	tests := []TestCase{
		{
			description: "Boundary: quantity 9 (No discount)",
			price:       100.0,
			quantity:    9,
			expected:    900.0,
		},
		{
			description: "Boundary: quantity 10 (10% discount begins)",
			price:       100.0,
